def isolated(variants, args, workers):
    """One process per variant, all at once: settings read at import (ORCH_E, ORCH_T) or process-wide (goal
    patches, ORCH_CURVE) then apply to that variant only, and the variants still meet the same suppliers at
    the same time. The sessions are split between the processes."""
    each = max(1, workers // len(variants))
    procs = []
    for v in variants:
        cmd = [sys.executable, "-u", __file__, v["name"], "-n", str(args.repeats), "--cases", args.cases]
        cmd += ["--parallel", str(each), "--data", args.data] + (["--seed", str(args.seed)] if args.seed else [])
        env = {**os.environ, **{k: str(x) for k, x in v.get("env", {}).items()}}
        procs.append(subprocess.Popen(cmd, env=env))
    for p in procs:
        p.wait()
    report([v["name"] for v in variants])


