    n.cfg = VARIANTS["A9h"][1]
    assert n.owes_step(eng.Thread(F1, [quote(52.0, body=ASK_BOSS)])) is False  # off in the final build


class Rest:
    """RFQ: J1 answers our first mail with a half step and 'we need to clarify this internally' (its rest follows on
    its next reply); C1's offers are acceptable all along."""

    def __init__(self):
        self.sent, self.log, self.lock = {J1: 0, C1: 0}, [], threading.Lock()

    def _ctx(self):
        pass

    def open_session(self, case_id):
        return {"session_id": "s1", "case": RFQ_CASE,
                "threads": {J1: [rfq_quote(J1, 17.1)], C1: [rfq_quote(C1, 16.0, pay=45, inco="EXW")]}}

    def attachment(self, session_id, attachment_id):
        return b""

    def session(self, session_id):
        return {"status": "open"}

    def thread(self, session_id, supplier_id):
        raise AssertionError("no resync expected")

    def send_message(self, session_id, sup, msg):
        if msg.get("action"):
