                self.log.append(("accept", sup, msg["action"].get("term_sheet_id")))
            return {"result": {"deal": True, "supplier_id": sup, "score": 0.7, "terms": {}}}
        with self.lock:
            self.sent[sup] += 1
            k = self.sent[sup]
            self.log.append(("msg", sup, k))
        if sup == J1:
