                r["body"] = "We need to clarify this internally - we will come back to you on price."
                return r
            r = rfq_quote(J1, 13.6, n=k, status="final_offer")
            r["body"] = "We have clarified this internally and can move further on the price."
            return r
        return rfq_quote(C1, 15.0, n=k, status="final_offer", pay=14)


def test_an_rfq_is_never_closed_while_a_bidder_owes_its_rest(monkeypatch):
